					return [{"depth":2,"slug":"understanding-paper-weight-notation","text":"Understanding Paper Weight Notation"},{"depth":2,"slug":"direct-mail-postcard-stock","text":"Direct Mail Postcard Stock"},{"depth":3,"slug":"100-lb-gloss-cover-standard","text":"100 lb. Gloss Cover (Standard)"},{"depth":3,"slug":"100-lb-matte-cover-premium-alternative","text":"100 lb. Matte Cover (Premium Alternative)"},{"depth":3,"slug":"14-pt-card-stock","text":"14 pt. Card Stock"},{"depth":2,"slug":"brochure-and-self-mailer-stock","text":"Brochure and Self-Mailer Stock"},{"depth":3,"slug":"100-lb-gloss-text","text":"100 lb. Gloss Text"},{"depth":3,"slug":"100-lb-matte-text","text":"100 lb. Matte Text"},{"depth":3,"slug":"80-lb-gloss-or-matte-text","text":"80 lb. Gloss or Matte Text"},{"depth":2,"slug":"letter-package-paper","text":"Letter Package Paper"},{"depth":3,"slug":"6070-lb-uncoated-text","text":"60–70 lb. Uncoated Text"},{"depth":3,"slug":"80-lb-uncoated-text","text":"80 lb. Uncoated Text"},{"depth":2,"slug":"coatings-what-they-do-and-when-to-use-each","text":"Coatings: What They Do and When to Use Each"},{"depth":3,"slug":"uv-coating","text":"UV Coating"},{"depth":3,"slug":"aqueous-aq-coating","text":"Aqueous (AQ) Coating"},{"depth":3,"slug":"matte-coating","text":"Matte Coating"},{"depth":3,"slug":"no-coating-uncoated","text":"No Coating (Uncoated)"},{"depth":2,"slug":"the-practical-recommendation","text":"The Practical Recommendation"},{"depth":2,"slug":"common-paper-stock-mistakes-in-direct-mail","text":"Common Paper Stock Mistakes in Direct Mail"},{"depth":2,"slug":"environmental-considerations","text":"Environmental Considerations"}];
